define("local_coursegenerator/tts",[],(function(){"use strict";
function createButton(labels){var button=document.createElement("button");button.type="button";button.className="btn btn-secondary btn-sm coursegenerator-tts-btn mt-2";button.textContent=labels.play;return button}
function wireButton(button,textEl,labels){var synth=window.speechSynthesis;var state="idle";var utterance=null;var reset=function(){state="idle";button.textContent=labels.play};button.addEventListener("click",(function(){if(state==="idle"){synth.cancel();utterance=new SpeechSynthesisUtterance(textEl.textContent.trim());utterance.lang=document.documentElement.lang||"es-ES";utterance.addEventListener("end",reset);utterance.addEventListener("error",reset);synth.speak(utterance);state="playing";button.textContent=labels.pause}else if(state==="playing"){synth.pause();state="paused";button.textContent=labels.resume}else{synth.resume();state="playing";button.textContent=labels.pause}}))}
var init=function(headings,labels){if(!("speechSynthesis" in window)){return}document.querySelectorAll("h3").forEach((function(heading){var text=heading.textContent.trim();if(text!==headings.content&&text!==headings.question){return}if(heading.dataset.cgTtsReady){return}heading.dataset.cgTtsReady="1";var textEl=heading.nextElementSibling;if(!textEl){return}var button=createButton(labels);textEl.insertAdjacentElement("afterend",button);wireButton(button,textEl,labels)}))};
return{init:init}}));
